import Particles, { ParticlesProvider } from "@tsparticles/react";
import { loadSlim } from "@tsparticles/slim";
import { useEffect, useRef } from "react";
import { usePreferences } from "../hooks/usePreferences";

export function ParticleField() {
  const { resolvedTheme, motionEnabled } = usePreferences();
  const fieldRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!motionEnabled) return;
    let frame = 0;
    const handlePointerMove = (event: PointerEvent) => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        const x = `${(event.clientX / window.innerWidth) * 100}%`;
        const y = `${(event.clientY / window.innerHeight) * 100}%`;
        fieldRef.current?.style.setProperty("--pointer-x", x);
        fieldRef.current?.style.setProperty("--pointer-y", y);
        frame = 0;
      });
    };
    window.addEventListener("pointermove", handlePointerMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [motionEnabled]);

  if (!motionEnabled) return null;

  const light = resolvedTheme === "light";
  return (
    <div ref={fieldRef} className="ambient-field" aria-hidden="true">
      <span className="ambient-orb ambient-orb--primary" />
      <span className="ambient-orb ambient-orb--secondary" />
      <span className="ambient-orb ambient-orb--tertiary" />
      <ParticlesProvider init={loadSlim}>
        <Particles
          id={`hyx-particles-${resolvedTheme}`}
          key={resolvedTheme}
          className="particle-field"
          options={{
            fullScreen: { enable: false },
            detectRetina: true,
            fpsLimit: 60,
            interactivity: {
              events: {
                onHover: { enable: true, mode: "grab" },
                onClick: { enable: true, mode: "push" },
              },
              modes: {
                grab: { distance: 180, links: { opacity: 0.55 } },
                push: { quantity: 3 },
              },
            },
            particles: {
              color: { value: light ? ["#006b82", "#334155", "#b45309"] : ["#61dafb", "#a7f3d0", "#ffbd6e"] },
              links: { color: light ? "#64748b" : "#42646d", distance: 160, enable: true, opacity: light ? 0.2 : 0.24, width: 1 },
              move: { direction: "none", enable: true, outModes: { default: "bounce" }, random: true, speed: 0.65, straight: false },
              number: { density: { enable: true, width: 850, height: 650 }, value: 86 },
              opacity: { animation: { enable: true, speed: 0.6, sync: false }, value: { min: 0.3, max: 0.82 } },
              shape: { type: "circle" },
              size: { value: { min: 0.9, max: 2.8 } },
            },
            pauseOnBlur: true,
            pauseOnOutsideViewport: true,
            responsive: [
              { maxWidth: 700, options: { particles: { number: { value: 36 }, links: { distance: 110 } } } },
            ],
          }}
        />
      </ParticlesProvider>
    </div>
  );
}
